import { openLandMap } from './land-map.js';
import { CROPS, DEMO_LOGIN, seedFarmer, emptyFarmer, revenue, analyzeField, exampleForecast, exampleClimate, compareCrops } from './model.js';

const app = document.getElementById('app');
const STORE = 'kisaan-farmer-workspace-v1', SESSION = 'kisaan-demo-session';
let profiles = [], farmer = null, loginTab = 'login', result = null, weatherField = '', historyTab = 'harvests';
let revenueTab='sale', revenueField='', revenueCrop='', buyerCrop='all', buyerDistrict='all', weatherOutlook='week', outlookYear=2027, outlookSeason=6;
