function cropMatchCards(f, matches, sowing, water) {
  return `<section class="card crop-matches" style="margin-top:28px"><div class="card-head"><div><div class="eyebrow">YOUR LAND · YOUR NEXT SEASON</div><h2>Best crops for this land</h2><p>${esc(f.name)} · ${num(f.area,2)} ha / ${num(f.area / .40468564224,2)} acres · ${esc(f.location)}</p></div><span class="badge amber">DEMO COMPARISON</span></div><div class="hint">${esc(f.waterSource || (f.irrigation === 'Rainfed' ? 'Rain only' : 'Borewell'))} · ${esc(f.irrigation)} · ${esc(f.soil)}. Screening uses the entered irrigation amount; soil and water-source reliability are not modeled.</div><form id="weather-crops-form" class="comparison-form"><div class="field"><label for="compare-sowing">Compare for sowing date</label><input id="compare-sowing" name="sowing" type="date" value="${esc(sowing)}" required></div><div class="field"><label for="compare-water">Available irrigation (mm / season)</label><input id="compare-water" name="water" type="number" min="0" max="10000" step="any" value="${water}" required></div><button class="btn secondary">Compare crops</button><p class="error" id="weather-crops-error" role="alert"></p></form><p class="safety-note">Coordinates select one of three fictional climate profiles, not real local weather. All crops use the same season and location. Ranked by temperature/water/sowing-season factor, then margin after sample costs. A short-term forecast cannot predict a whole-season harvest.</p><div class="crop-match-grid">${matches.map((r,i)=>`<article class="crop-match ${i===0?'best-match':''}"><div class="row between"><span class="crop-emoji">${CROPS[r.crop].emoji}</span><span class="badge ${i===0?'':'gray'}">${i===0?(r.factor===1?'Top demo match':'Closest demo match'):'#'+(i+1)}</span></div><h3>${r.cropName}</h3><p class="small muted">${r.fit}</p><div class="fit-track"><i style="width:${r.factor*100}%"></i></div><p class="small muted">${num(r.factor*100)}% scenario factor</p><div class="guide-line"><span>Total yield</span><strong>${num(r.totalKg)} kg</strong></div><div class="guide-line"><span>Yield / hectare</span><strong>${num(r.perHa)} kg</strong></div><div class="guide-line"><span>Gross sales</span><strong>${inr(r.gross)}</strong></div><div class="guide-line"><span>Sample cost</span><strong>${inr(r.cost)}</strong></div><div class="guide-line"><span>After sample costs</span><strong>${inr(r.net)}</strong></div><div class="guide-line"><span>Assumed price</span><strong>${inr(r.price)} / q</strong></div><p class="small muted">${num(r.historical.temp,1)}°C seasonal average · ${num(r.historical.rain)} mm rain + ${num(r.water)} mm irrigation.</p><p class="small muted">${r.waterGap>0?num(r.waterGap)+' mm below the lower seasonal water guide.':'Lower seasonal water guide reached in this example.'}</p><button class="text-btn" data-action="match-plan" data-crop="${r.crop}">Explore & save this plan ${icon('arrow')}</button></article>`).join('')}</div></section>`;
}




function revenueView() {
  const tabs=`<div class="tabs revenue-tabs"><button data-action="revenue-tab" data-tab="sale" class="${revenueTab==='sale'?'active':''}">Sale calculator</button><button data-action="revenue-tab" data-tab="estimate" class="${revenueTab==='estimate'?'active':''}">Estimated yield & revenue</button><button data-action="revenue-tab" data-tab="buyers" class="${revenueTab==='buyers'?'active':''}">Find a buyer</button></div>`;
  return tabs+(revenueTab==='sale'?saleCalculatorView():revenueTab==='estimate'?estimatedRevenueView():buyersView());
}
function estimatedRevenueView() {
  const f=farmer.fields.find(f=>f.id===revenueField)||farmer.fields[0];
  if(!f)return head('Plan your harvest earnings.','Add a field before estimating its yield and revenue.')+'<a href="#fields" class="btn">Add your land</a>';
  const crop=revenueCrop||f.crop, c=CROPS[crop], r=compareCrops(f).find(r=>r.crop===crop), base=r.cost, irrigationShare=(f.waterMm??(f.irrigation==='Rainfed'?0:200))>0?.15:0;
  return `${head('Plan your harvest earnings.','Estimate production, sales and costs for the land you select.','<span class="badge amber">DEMO ESTIMATE</span>','ESTIMATED YIELD & REVENUE')}<div class="grid2"><section class="card"><form id="estimate-revenue-form"><div class="form-grid"><div class="field span2"><label for="estimate-field">Estimate for field</label><select id="estimate-field" name="field" data-change="estimate-field">${farmer.fields.map(field=>`<option value="${esc(field.id)}" ${field.id===f.id?'selected':''}>${esc(field.name)} · ${num(field.area,2)} ha</option>`).join('')}</select></div><div class="field"><label for="estimate-crop">Revenue crop</label><select id="estimate-crop" name="crop" data-change="estimate-crop">${cropOptions(crop)}</select></div>${inputField('estimate-sowing','Estimated sowing date',f.sowing,'type="date" required')}${inputField('estimate-water','Available irrigation (mm / season)',f.waterMm??(f.irrigation==='Rainfed'?0:200),'type="number" min="0" step="any" required')}${inputField('estimate-price','Expected price (₹/quintal)',c.price,'type="number" min="0" step="any" required')}${inputField('estimate-inputs','Seed, nutrients & crop care (₹)',Math.round(base*(.8-irrigationShare)),'type="number" min="0" step="any" required')}${inputField('estimate-labour','Labour & equipment (₹)',Math.round(base*.2),'type="number" min="0" step="any" required')}${inputField('estimate-water-cost','Irrigation cost (₹)',Math.round(base*irrigationShare),'type="number" min="0" step="any" required')}${inputField('estimate-sale-cost','Transport & selling charges (₹)',0,'type="number" min="0" step="any" required')}</div><p class="safety-note">${esc(f.location)} · ${num(f.area,2)} ha · ${esc(f.waterSource||f.irrigation)}. Prices and costs are editable sample assumptions for the whole field.</p><p id="estimate-revenue-error" class="error" role="alert"></p><button class="btn wide">Estimate yield & revenue</button></form></section><section class="card" id="estimate-revenue-result">${estimateEarningsSummary(r,{inputs:Math.round(base*(.8-irrigationShare)),labour:Math.round(base*.2),waterCost:Math.round(base*irrigationShare),saleCost:0})}</section></div>`;
}
function estimateEarningsSummary(r,costs){
  const total=Object.values(costs).reduce((a,b)=>a+b,0), net=r.gross-total;
  return `<div class="eyebrow">${r.cropName.toUpperCase()} · ${num(r.areaHa,2)} HECTARES</div><h2 style="margin:12px 0">Your harvest-to-income estimate</h2><span class="badge gray">${esc(r.fit)}</span><div class="result-metrics"><div><div class="metric-label">Estimated yield</div><div class="metric-value">${num(r.totalKg)} <small>kg</small></div><p class="small muted">${num(r.totalKg/100)} quintals · ${num(r.perHa)} kg/ha</p></div><div><div class="metric-label">Estimated gross revenue</div><div class="metric-value">${inr(r.gross)}</div><p class="small muted">${inr(r.price)} per quintal</p></div></div><div class="divider"></div><div class="earnings-breakdown">${[['Seed, nutrients & crop care',costs.inputs],['Labour & equipment',costs.labour],['Irrigation',costs.waterCost],['Transport & selling',costs.saleCost],['Total costs',total]].map(([label,value])=>`<div class="guide-line"><span>${label}</span><strong>${inr(value)}</strong></div>`).join('')}<div class="guide-line"><span>Expected margin after entered costs</span><strong class="${net<0?'loss':'trend'}">${inr(net)}</strong></div><div class="guide-line"><span>Margin on gross sales</span><strong>${r.gross?num(net/r.gross*100,1)+'%':'—'}</strong></div><div class="guide-line"><span>Break-even price</span><strong>${r.totalKg>0?inr(total/(r.totalKg/100))+' / q':'—'}</strong></div><div class="guide-line"><span>Illustrative harvest date</span><strong>${shortDate(r.harvestDate)}</strong></div></div><div class="hint" style="margin-top:20px">Yield sensitivity: ${num(r.lowKg)}–${num(r.highKg)} kg. Gross revenue: ${inr(r.lowRevenue)}–${inr(r.highRevenue)}. Margin after entered costs: ${inr(r.lowRevenue-total)}–${inr(r.highRevenue-total)}.</div><p class="safety-note">±25% illustrative sensitivity, not a confidence interval. Forecast uses seeded climate, a sample reference yield and simple arithmetic. Unentered costs, quality deductions and taxes are excluded. This is not guaranteed profit.</p><button class="btn secondary wide" data-action="revenue-tab" data-tab="buyers" data-crop="${r.crop}">Find a buyer for this harvest</button>`;
}
