function buyersView(){const buyers=demoBuyers.filter(b=>(buyerCrop==='all'||b.crop===buyerCrop)&&(buyerDistrict==='all'||b.district===buyerDistrict));return `${head('Find the next home for your harvest.','Explore buyers for your crop and save a shortlist.','<span class="badge amber">FICTIONAL BUYERS</span>','FIND A BUYER')}<div class="hint">All names, offers and requirements here are dummy data. Saving a buyer only updates this browser; it does not contact anyone or create a sale.</div><div class="comparison-form"><div class="field"><label for="buyer-crop">Buyer crop</label><select id="buyer-crop" data-change="buyer-crop"><option value="all">All crops</option>${cropOptions(buyerCrop)}</select></div><div class="field"><label for="buyer-district">Buyer district</label><select id="buyer-district" data-change="buyer-district">${['all','Yavatmal','Nagpur','Wardha'].map(d=>`<option value="${d}" ${d===buyerDistrict?'selected':''}>${d==='all'?'All demo districts':d}</option>`).join('')}</select></div><span class="badge gray">${buyers.length} SAMPLE LISTINGS</span></div><div class="grid3">${buyers.map(b=>`<article class="card"><span class="crop-emoji">${CROPS[b.crop].emoji}</span><h3 style="margin:15px 0 7px">${b.name}</h3><p class="small muted">${b.kind} · ${b.district}</p><span class="badge gray">${CROPS[b.crop].name}</span><div class="guide-line" style="margin-top:18px"><span>Sample offer</span><strong>${inr(b.price)} / q</strong></div><div class="guide-line"><span>Minimum lot</span><strong>${num(b.min)} kg</strong></div><p class="small muted">${b.delivery}</p><p class="safety-note">Price depends on grade, moisture and negotiation in a future real marketplace.</p><button class="btn secondary wide" data-action="save-buyer" data-id="${b.id}" ${(farmer.savedBuyers||[]).includes(b.id)?'disabled':''}>${(farmer.savedBuyers||[]).includes(b.id)?'Saved to your shortlist':'Save buyer'}</button></article>`).join('')}</div>${buyers.length?'':'<section class="card"><p>No demo listings match. Choose another crop or district.</p></section>'}<p class="safety-note">Backend phase: verified buyer accounts, requests for quotes, availability, quality checks and contact options.</p>`;}

function weatherForecastPanel(f){
 const tabs=`<div class="tabs" style="margin-bottom:18px"><button data-action="weather-outlook" data-tab="week" class="${weatherOutlook==='week'?'active':''}">7-day outlook</button><button data-action="weather-outlook" data-tab="season" class="${weatherOutlook==='season'?'active':''}">Next year & harvest</button></div>`;
 if(weatherOutlook==='week')return tabs+forecastView(f);
 const names=['Jan','Feb','Mar','Apr','May','Jun','Jul','Aug','Sep','Oct','Nov','Dec'];
 const climate=exampleClimate(f?.crop||'cotton',6,f), ratio=climate.rain/829 * ([.96,1.04,1][(outlookYear-2027)%3]);
 const rain=[8,12,20,25,42,150,225,180,125,65,15,8].map(n=>Math.round(n*ratio));
 const temperatures=[23,25,29,33,35,31,28,28,29,29,26,23].map(t=>t+climate.temp-28);
 const ranked=f?compareCrops(f,{sowing:outlookYear+'-'+String(outlookSeason).padStart(2,'0')+'-15',water:weatherInputs.water??f.waterMm??(f.irrigation==='Rainfed'?0:200)}):[];
 const c=CROPS[ranked[0]?.crop||'cotton'], sowing=outlookYear+'-'+String(outlookSeason).padStart(2,'0')+'-15',harvest=new Date(sowing+'T12:00:00Z');harvest.setUTCDate(harvest.getUTCDate()+c.days);
 return tabs+`<div class="row between"><div><span class="badge amber">FICTIONAL ANNUAL SCENARIO</span><p class="small muted">${esc(f?.location||farmer.village)} · ${climate.profile}</p></div><div class="field"><label for="outlook-year">Outlook year</label><select id="outlook-year" data-change="outlook-year">${[2027,2028,2029].map(y=>`<option ${y===outlookYear?'selected':''}>${y}</option>`).join('')}</select></div></div><div class="season-months">${names.map((m,i)=>`<div><strong>${Math.round(temperatures[i])}°</strong><i style="height:${rain[i]/Math.max(...rain)*85}px"></i><span>${m}</span><small>${rain[i]} mm</small></div>`).join('')}</div><div class="grid2" style="margin-top:20px"><div class="hint"><strong>${num(rain.reduce((a,b)=>a+b,0))} mm</strong><br>Example annual rainfall<br>Warmest: May · wetter: Jul–Aug</div><div class="hint"><strong>${c.name} harvest window</strong><br>Demo planned sowing: ${shortDate(sowing)}<br>Illustrative harvest: ${shortDate(harvest.toISOString().slice(0,10))}</div></div><p class="safety-note">This annual chart is a fixed presentation scenario, not a long-range forecast. Year changes select a fictional scenario, not a forecast. The harvest window uses the selected year, planting window and top demo crop’s duration. Your saved field is unchanged.</p><div class="divider"></div><div class="field"><label for="outlook-season">Crop planning window</label><select id="outlook-season" data-change="outlook-season"><option value="6" ${outlookSeason===6?'selected':''}>Monsoon planting · June</option><option value="11" ${outlookSeason===11?'selected':''}>Winter planting · November</option></select></div><h3 style="margin-top:18px">Best crops for this estimated weather</h3><p class="small muted">Ranked using a seeded seasonal climate for ${outlookYear}, the saved land area and available irrigation. The annual chart provides context; crop screening uses the selected planting season.</p><div class="grid3">${ranked.slice(0,3).map((r,i)=>`<div class="hint"><strong>${i+1}. ${r.cropName}</strong><br>${r.fit}<br>${num(r.totalKg)} kg · ${inr(r.gross)} gross<br>${inr(r.net)} after sample costs<br><span class="small">${num(r.historical.temp,1)}°C · ${num(r.historical.rain)} mm seasonal rain</span></div>`).join('')}</div><p class="safety-note">Crop comparisons use the same three fictional seasonal profiles across years. No climate change or real forecast signal is modeled.</p><div class="divider"></div><h3>What to watch through the season</h3><p class="small muted">Mar–May: example heat and low rainfall—review water availability. Jun–Sep: example rainy season—review drainage and crop-stage needs. Oct–Feb: cooler example conditions—compare a winter sowing window.</p>`;
}


